body:
[nitpick] Consider refactoring this into a table-driven test to reduce repetition and make adding new cases easier. Define a slice of test cases with input `BackupResults` and expected `ok`/`failed` counts, then range over them.
```suggestion
	testCases := []struct {
		name     string
		input    BackupResults
		expectedOk     int
		expectedFailed int
	}{
		{
			name: "two success",
			input: BackupResults{Results: &[]ProviderBackupResults{{
				Provider: "test",
				Results: githosts.ProviderBackupResult{
					BackupResults: []githosts.RepoBackupResults{{Repo: "a"}, {Repo: "b"}},
				},
			}}},
			expectedOk:     2,
			expectedFailed: 0,
		},
		{
			name: "one failed provider error",
			input: BackupResults{Results: &[]ProviderBackupResults{{
				Provider: "test",
				Results:  githosts.ProviderBackupResult{Error: tozdErrors.New("err")},
			}}},
			expectedOk:     0,
			expectedFailed: 1,
		},
		{
			name: "repo error counts as failed",
			input: BackupResults{Results: &[]ProviderBackupResults{{
				Provider: "test",
				Results: githosts.ProviderBackupResult{
					BackupResults: []githosts.RepoBackupResults{{Repo: "a", Error: tozdErrors.New("boom")}},
				},
			}}},
			expectedOk:     0,
			expectedFailed: 1,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			ok, failed := getBackupsStats(tc.input)
			require.Equal(t, tc.expectedOk, ok)
			require.Equal(t, tc.expectedFailed, failed)
		})
	}
```

